CREATE TABLE health_facilities (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), name VARCHAR(160) NOT NULL, facility_type VARCHAR(40) NOT NULL, service_status VARCHAR(30) NOT NULL DEFAULT 'UNKNOWN', beds_available INTEGER NOT NULL DEFAULT 0 CHECK(beds_available >= 0), oxygen_available BOOLEAN NOT NULL DEFAULT FALSE, updated_by UUID REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_health_facilities_community ON health_facilities(community_id,service_status);
CREATE TABLE transport_vehicles (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), vehicle_code VARCHAR(40) NOT NULL, vehicle_type VARCHAR(40) NOT NULL, capacity INTEGER NOT NULL CHECK(capacity > 0), status VARCHAR(24) NOT NULL DEFAULT 'AVAILABLE', latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(community_id,vehicle_code), CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90), CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE INDEX idx_transport_vehicles_community_status ON transport_vehicles(community_id,status);
CREATE TABLE transport_requests (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), request_type VARCHAR(40) NOT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'NORMAL', pickup_latitude DOUBLE PRECISION NOT NULL, pickup_longitude DOUBLE PRECISION NOT NULL, destination_latitude DOUBLE PRECISION NOT NULL, destination_longitude DOUBLE PRECISION NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'NEW', notes VARCHAR(500), requested_by UUID REFERENCES app_users(id), assigned_vehicle_id UUID REFERENCES transport_vehicles(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK(pickup_latitude BETWEEN -90 AND 90), CHECK(pickup_longitude BETWEEN -180 AND 180), CHECK(destination_latitude BETWEEN -90 AND 90), CHECK(destination_longitude BETWEEN -180 AND 180));
CREATE INDEX idx_transport_requests_community_status ON transport_requests(community_id,status,priority,created_at);
